import{_ as t,a0 as l,w as o,s as r,ao as d,I as i,x as a,a1 as e,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"如何修复 WordPress 中的 HTTP 错误 | LCTT x X-CMD","titleTemplate":false,"description":"如何修复 WordPress 中的 HTTP 错误 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何修复 WordPress 中的 HTTP 错误 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何修复 WordPress 中的 HTTP 错误 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20180102 HTTP errors in WordPress","title":"如何修复 WordPress 中的 HTTP 错误","tag":"201803","desc":""},"relativePath":"201803/20180102 HTTP errors in WordPress.md","filePath":"[post].md"}'),c={name:"201803/20180102 HTTP errors in WordPress.md"};function h(g,s,u,k,b,f){const n=l("Link");return o(),r("div",null,[s[13]||(s[13]=d(`<h1 id="如何修复-wordpress-中的-http-错误" tabindex="-1">如何修复 WordPress 中的 HTTP 错误 <a class="header-anchor" href="#如何修复-wordpress-中的-http-错误" aria-label="Permalink to “如何修复 WordPress 中的 HTTP 错误”">​</a></h1><p><img src="https://www.rosehosting.com/blog/wp-content/uploads/2018/01/http-error-wordpress.jpg" alt="http error wordpress"></p><p>我们会向你介绍，如何在 Linux VPS 上修复 WordPress 中的 HTTP 错误。 下面列出了 WordPress 用户遇到的最常见的 HTTP 错误，我们的建议侧重于如何发现错误原因以及解决方法。</p><h3 id="_1、-修复在上传图像时出现的-http-错误" tabindex="-1">1、 修复在上传图像时出现的 HTTP 错误 <a class="header-anchor" href="#_1、-修复在上传图像时出现的-http-错误" aria-label="Permalink to “1、 修复在上传图像时出现的 HTTP 错误”">​</a></h3><p>如果你在基于 WordPress 的网页中上传图像时出现错误，这也许是因为服务器上 PHP 的配置，例如存储空间不足或者其他配置问题造成的。</p><p>用如下命令查找 php 配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>php -i | grep php.ini</span></span>
<span class="line"><span>Configuration File (php.ini) Path =&gt; /etc</span></span>
<span class="line"><span>Loaded Configuration File =&gt; /etc/php.ini</span></span></code></pre></div><p>根据输出结果，php 配置文件位于 <code>/etc</code> 文件夹下。编辑 <code>/etc/php.ini</code> 文件，找出下列行，并按照下面的例子修改其中相对应的值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vi /etc/php.ini</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>upload_max_filesize = 64M</span></span>
<span class="line"><span>post_max_size = 32M</span></span>
<span class="line"><span>max_execution_time = 300</span></span>
<span class="line"><span>max_input_time 300</span></span>
<span class="line"><span>memory_limit = 128M</span></span></code></pre></div><p>当然，如果你不习惯使用 vi 文本编辑器，你可以选用自己喜欢的。</p><p>不要忘记重启你的网页服务器来让改动生效。</p><p>如果你安装的网页服务器是 Apache，你也可以使用 <code>.htaccess</code> 文件。首先，找到 <code>.htaccess</code> 文件。它位于 WordPress 安装路径的根文件夹下。如果没有找到 <code>.htaccess</code> 文件，需要自己手动创建一个，然后加入如下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vi /www/html/path_to_wordpress/.htaccess</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>php_value upload_max_filesize 64M</span></span>
<span class="line"><span>php_value post_max_size 32M</span></span>
<span class="line"><span>php_value max_execution_time 180</span></span>
<span class="line"><span>php_value max_input_time 180</span></span>
<span class="line"><span></span></span>
<span class="line"><span># BEGIN WordPress</span></span>
<span class="line"><span>&lt;IfModule mod_rewrite.c&gt;</span></span>
<span class="line"><span>  RewriteEngine On</span></span>
<span class="line"><span>  RewriteBase /</span></span>
<span class="line"><span>  RewriteRule ^index\\.php$ - [L]</span></span>
<span class="line"><span>  RewriteCond %{REQUEST_FILENAME} !-f</span></span>
<span class="line"><span>  RewriteCond %{REQUEST_FILENAME} !-d</span></span>
<span class="line"><span>  RewriteRule . /index.php [L]</span></span>
<span class="line"><span>&lt;/IfModule&gt;</span></span>
<span class="line"><span># END WordPress</span></span></code></pre></div><p>如果你使用的网页服务器是 nginx，在 nginx 的 <code>server</code> 配置块中配置你的 WordPress 实例。详细配置和下面的例子相似：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>server {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  listen 80;</span></span>
<span class="line"><span>  client_max_body_size 128m;</span></span>
<span class="line"><span>  client_body_timeout 300;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  server_name your-domain.com www.your-domain.com;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  root /var/www/html/wordpress;</span></span>
<span class="line"><span>  index index.php;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  location = /favicon.ico {</span></span>
<span class="line"><span>  log_not_found off;</span></span>
<span class="line"><span>  access_log off;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  location = /robots.txt {</span></span>
<span class="line"><span>    allow all;</span></span>
<span class="line"><span>    log_not_found off;</span></span>
<span class="line"><span>    access_log off;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  location / {</span></span>
<span class="line"><span>    try_files $uri $uri/ /index.php?$args;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  location ~ \\.php$ {</span></span>
<span class="line"><span>    include fastcgi_params;</span></span>
<span class="line"><span>    fastcgi_pass 127.0.0.1:9000;</span></span>
<span class="line"><span>    fastcgi_index index.php;</span></span>
<span class="line"><span>    fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  location ~* \\.(js|css|png|jpg|jpeg|gif|ico)$ {</span></span>
<span class="line"><span>    expires max;</span></span>
<span class="line"><span>    log_not_found off;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>根据自己的 PHP 配置，你需要将 <code>fastcgi_pass 127.0.0.1:9000;</code> 用类似于 <code>fastcgi_pass unix:/var/run/php7-fpm.sock;</code> 替换掉（依照实际连接方式）</p><p>重启 nginx 服务来使改动生效。</p><h3 id="_2、-修复因为不恰当的文件权限而产生的-http-错误" tabindex="-1">2、 修复因为不恰当的文件权限而产生的 HTTP 错误 <a class="header-anchor" href="#_2、-修复因为不恰当的文件权限而产生的-http-错误" aria-label="Permalink to “2、 修复因为不恰当的文件权限而产生的 HTTP 错误”">​</a></h3><p>如果你在 WordPress 中出现一个意外错误，也许是因为不恰当的文件权限导致的，所以需要给 WordPress 文件和文件夹设置一个正确的权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>chown www-data:www-data -R /var/www/html/path_to_wordpress/</span></span></code></pre></div><p>将 <code>www-data</code> 替换成实际的网页服务器用户，将 <code>/var/www/html/path_to_wordpress</code> 换成 WordPress 的实际安装路径。</p><h3 id="_3、-修复因为内存不足而产生的-http-错误" tabindex="-1">3、 修复因为内存不足而产生的 HTTP 错误 <a class="header-anchor" href="#_3、-修复因为内存不足而产生的-http-错误" aria-label="Permalink to “3、 修复因为内存不足而产生的 HTTP 错误”">​</a></h3><p>你可以通过在 <code>wp-config.php</code> 中添加如下内容来设置 PHP 的最大内存限制：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>define(&#39;WP_MEMORY_LIMIT&#39;, &#39;128MB&#39;);</span></span></code></pre></div><h3 id="_4、-修复因为-php-ini-文件错误配置而产生的-http-错误" tabindex="-1">4、 修复因为 php.ini 文件错误配置而产生的 HTTP 错误 <a class="header-anchor" href="#_4、-修复因为-php-ini-文件错误配置而产生的-http-错误" aria-label="Permalink to “4、 修复因为 php.ini 文件错误配置而产生的 HTTP 错误”">​</a></h3><p>编辑 PHP 配置主文件，然后找到 <code>cgi.fix_pathinfo</code> 这一行。 这一行内容默认情况下是被注释掉的，默认值为 <code>1</code>。取消这一行的注释（删掉这一行最前面的分号），然后将 <code>1</code> 改为 <code>0</code> 。同时需要修改 <code>date.timezone</code> 这一 PHP 设置，再次编辑 PHP 配置文件并将这一选项改成 <code>date.timezone = Asia/Shanghai</code> （或者将等号后内容改为你所在的时区）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vi /etc/php.ini</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cgi.fix_pathinfo=0</span></span>
<span class="line"><span>date.timezone = Asia/Shanghai</span></span></code></pre></div><h3 id="_5、-修复因为-apache-mod-security-模块而产生的-http-错误" tabindex="-1">5、 修复因为 Apache mod_security 模块而产生的 HTTP 错误 <a class="header-anchor" href="#_5、-修复因为-apache-mod-security-模块而产生的-http-错误" aria-label="Permalink to “5、 修复因为 Apache mod_security 模块而产生的 HTTP 错误”">​</a></h3><p>如果你在使用 Apache mod_security 模块，这可能也会引起问题。试着禁用这一模块，确认是否因为在 <code>.htaccess</code> 文件中加入如下内容而引起了问题：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;IfModule mod_security.c&gt;</span></span>
<span class="line"><span>  SecFilterEngine Off</span></span>
<span class="line"><span>  SecFilterScanPOST Off</span></span>
<span class="line"><span>&lt;/IfModule&gt;</span></span></code></pre></div><h3 id="_6、-修复因为有问题的插件-主题而产生的-http-错误" tabindex="-1">6、 修复因为有问题的插件/主题而产生的 HTTP 错误 <a class="header-anchor" href="#_6、-修复因为有问题的插件-主题而产生的-http-错误" aria-label="Permalink to “6、 修复因为有问题的插件/主题而产生的 HTTP 错误”">​</a></h3><p>一些插件或主题也会导致 HTTP 错误以及其他问题。你可以首先禁用有问题的插件/主题，或暂时禁用所有 WordPress 插件。如果你有 phpMyAdmin，使用它来禁用所有插件：在其中找到 <code>wp_options</code> 数据表，在 <code>option_name</code> 这一列中找到 <code>active_plugins</code> 这一记录，然后将 <code>option_value</code> 改为 ：<code>a:0:{}</code>。</p><p>或者用以下命令通过SSH重命名插件所在文件夹：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mv /www/html/path_to_wordpress/wp-content/plugins /www/html/path_to_wordpress/wp-content/plugins.old</span></span></code></pre></div><p>通常情况下，HTTP 错误会被记录在网页服务器的日志文件中，所以寻找错误时一个很好的切入点就是查看服务器日志。</p><hr>`,39)),i("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.rosehosting.com/blog/http-error-wordpress/"},{default:p(()=>[...s[0]||(s[0]=[a("https://www.rosehosting.com/blog/http-error-wordpress/",-1)])]),_:1})]),i("p",null,[s[5]||(s[5]=a("作者：",-1)),e(n,{href:"https://www.rosehosting.com"},{default:p(()=>[...s[2]||(s[2]=[a("rosehosting",-1)])]),_:1}),s[6]||(s[6]=a(" 译者：",-1)),e(n,{href:"https://github.com/wenwensnow"},{default:p(()=>[...s[3]||(s[3]=[a("wenwensnow",-1)])]),_:1}),s[7]||(s[7]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[10]||(s[10]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[9]||(s[9]=[a("Linux中国",-1)])]),_:1}),s[12]||(s[12]=a(" 荣誉推出",-1))])])}const w=t(c,[["render",h]]);export{T as __pageData,w as default};
